export function render(c){
 const {main,state:s,t,esc,money,number,icon,button}=c,d=c.data();s.status||='all';const remote=c.D.cloud?c.cloudPage('bundles',s,12):null;if(c.D.cloud&&!remote)return;const now=Date.now(),active=b=>b.enabled&&(!b.startsAt||+new Date(b.startsAt)<=now)&&(!b.endsAt||+new Date(b.endsAt)>now),sales=b=>c.D.cloud?Number(d.summary.operational?.bundleSales?.[b.id]?.quantity)||0:c.sum(d.orders.filter(o=>o.statusKey!=='cancelled').flatMap(o=>o.items).filter(i=>i.bundleId===b.id||i.id===b.id),i=>i.quantity||1),revenue=b=>c.D.cloud?Number(d.summary.operational?.bundleSales?.[b.id]?.total)||0:c.sum(d.orders.filter(o=>o.statusKey!=='cancelled').flatMap(o=>o.items).filter(i=>i.bundleId===b.id||i.id===b.id),i=>(i.quantity||1)*i.price),rows=d.bundles.filter(b=>s.status==='all'||s.status==='active'&&active(b)||s.status==='inactive'&&!active(b));
 main.innerHTML=c.heading(t('الباقات والعروض المجمعة','Bundles and grouped offers'),t('اجمع منتجات متجرك بسعر محسوب وموعد بداية ونهاية واضح.','Combine your store’s products with a calculated price and clear start and end dates.'),button(t('باقة جديدة','New bundle'),'add','add'))+`<div class="aw-kpis">${[[t('الباقات النشطة','Active bundles'),number(c.D.cloud?d.summary.operational?.bundles?.active||0:d.bundles.filter(active).length),'redeem'],[t('باقات مباعة','Bundles sold'),number(c.sum(d.bundles,sales)),'shopping_bag'],[t('إيرادات الباقات','Bundle revenue'),money(c.sum(d.bundles,revenue)),'payments'],[t('إجمالي الباقات','Total bundles'),number(c.D.cloud?d.summary.operational?.bundles?.total||0:d.bundles.length),'inventory_2']].map(([label,value,i])=>`<article class="aw-panel aw-kpi"><div class="aw-kpi-top"><span class="aw-kpi-icon">${icon(i)}</span></div><p>${label}</p><strong>${value}</strong></article>`).join('')}</div><div class="aw-page-heading"><div class="aw-segments">${[['all',t('كل الباقات','All bundles')],['active',t('نشطة','Active')],['inactive',t('متوقفة / مجدولة','Paused / scheduled')]].map(([key,label])=>`<button data-status="${key}" aria-pressed="${s.status===key}">${label}</button>`).join('')}</div></div>${rows.length?`<div class="aw-grid">${rows.map(b=>{const products=b.productIds.map(id=>d.products.find(p=>p.id===id)).filter(Boolean),original=c.sum(products,p=>StoreProducts.getEffectivePrice(p).price),discount=Math.max(0,original-Number(b.price)),percent=original?Math.round(discount/original*100):0;return`<article class="aw-panel aw-product-card"><div class="aw-actions" style="justify-content:space-between"><span class="aw-badge aw-badge--${active(b)?'in':'new'}">${active(b)?t('نشطة','Active'):t('غير نشطة','Inactive')}</span><strong>${t('توفير','Save')} ${number(percent)}%</strong></div><h2 style="margin-block:16px">${esc(c.localized(b.title))}</h2><p class="aw-muted">${esc(c.localized(b.description)||'')}</p><div class="aw-list" style="margin-block:16px">${products.map(p=>`<div class="aw-product-cell">${c.image(p.image)}<div><strong>${esc(c.localized(p.name))}</strong><small>${money(StoreProducts.getEffectivePrice(p).price)}</small></div></div>`).join('')}</div><small><s>${money(original)}</s></small><strong class="aw-price" style="display:block">${money(b.price)}</strong><p class="aw-muted">${t('توفير','Save')} ${money(discount)}</p><div class="aw-stat-line"><small>${b.endsAt?t('تنتهي ','Ends ')+c.date(b.endsAt):t('بلا تاريخ انتهاء','No end date')}</small><small>${number(sales(b))} ${t('باقة مباعة','sold')}</small></div><label class="aw-check"><input type="checkbox" data-toggle="${esc(b.id)}" ${b.enabled?'checked':''}>${t('مفعلة في المتجر','Enabled in storefront')}</label><div class="aw-actions"><button class="aw-button aw-button--soft aw-button--small" data-edit="${esc(b.id)}">${icon('edit')}${t('تعديل','Edit')}</button>${c.canManage?`<button class="aw-button aw-button--danger aw-button--small" data-delete="${esc(b.id)}">${icon('delete')}${t('حذف','Delete')}</button>`:''}</div></article>`}).join('')}</div>`:c.empty(t('لا توجد باقات في هذه الحالة','No bundles in this state'),t('أنشئ باقة من منتجين أو أكثر لتبدأ.','Create a bundle with two or more products to get started.'),button(t('إنشاء باقة','Create bundle'),'add','add'))}`;
 main.onchange=async e=>{const id=e.target.dataset.toggle;if(!id)return;await c.run(()=>c.D.write('bundles',c.data().bundles.map(b=>b.id===id?{...b,enabled:e.target.checked}:b)));c.redraw()};
 main.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.status){s.status=b.dataset.status;s.page=1;c.redraw()}if(b.dataset.edit||b.dataset.action==='add')edit(c,b.dataset.edit);if(b.dataset.delete){const bundle=d.bundles.find(row=>row.id===b.dataset.delete);if(await c.confirm(t('حذف الباقة','Delete bundle'),c.localized(bundle.title))){const result=await c.run(()=>c.D.write('bundles',c.data().bundles.filter(row=>row.id!==bundle.id)),null);if(result!==false){c.toast(t('تم حذف الباقة','Bundle deleted'),()=>c.D.write('bundles',[...c.data().bundles,bundle]));c.redraw()}}}};
}
async function edit(c,id){if(c.D.cloud){try{if(id)await c.D.detail('bundles',id);await c.D.lookupProducts('',c.data().bundles.find(b=>b.id===id)?.productIds||[])}catch(error){c.toast(error.message);return}}
 const {t,esc,money}=c,d=c.data(),b=d.bundles.find(row=>row.id===id)||{id:'',title:{ar:'',en:''},description:{ar:'',en:''},productIds:[],price:0,enabled:true},selected=new Set(b.productIds),dialog=c.openDialog(id?t('تعديل الباقة','Edit bundle'):t('باقة جديدة','New bundle'),`<form class="aw-stack"><div class="aw-form-grid"><label class="aw-field">${t('الاسم بالعربية','Arabic title')}<input class="aw-input" name="titleAr" required value="${esc(b.title.ar)}"></label><label class="aw-field">${t('الاسم بالإنجليزية','English title')}<input class="aw-input" name="titleEn" required value="${esc(b.title.en)}"></label><label class="aw-field aw-field--full">${t('الوصف','Description')}<textarea class="aw-textarea" name="description">${esc(c.localized(b.description))}</textarea></label></div><label class="aw-field">${t('اختيار المنتجات (2 إلى 8)','Choose products (2 to 8)')}<input class="aw-input" data-bundle-search placeholder="${t('ابحث عن منتج…','Search products…')}"></label><div class="aw-list" data-bundle-products style="max-height:260px;overflow:auto"></div><div class="aw-detail-box"><div class="aw-stat-line"><span>${t('السعر الأصلي','Original price')}</span><strong data-original></strong></div><div class="aw-stat-line"><span>${t('التوفير','Savings')}</span><strong data-savings></strong></div></div><label class="aw-field">${t('سعر الباقة','Bundle price')}<input class="aw-input" type="number" min="0.01" step="0.01" name="price" required value="${b.price||''}"></label><div class="aw-form-grid"><label class="aw-field">${t('بداية العرض','Starts at')}<input class="aw-input" type="datetime-local" name="startsAt" value="${esc((b.startsAt||'').slice(0,16))}"></label><label class="aw-field">${t('نهاية العرض','Ends at')}<input class="aw-input" type="datetime-local" name="endsAt" value="${esc((b.endsAt||'').slice(0,16))}"></label></div><label class="aw-check"><input name="enabled" type="checkbox" ${b.enabled?'checked':''}>${t('مفعلة','Enabled')}</label><p class="aw-form-error" role="alert"></p><button class="aw-button" type="submit">${t('حفظ الباقة','Save bundle')}</button></form>`,{drawer:true}),form=dialog.querySelector('form');
 const total=()=>c.sum(d.products.filter(p=>selected.has(p.id)),p=>StoreProducts.getEffectivePrice(p).price),sync=()=>{const original=total(),saving=original-Number(form.price.value||0);dialog.querySelector('[data-original]').textContent=money(original);dialog.querySelector('[data-savings]').textContent=money(saving)+' · '+c.number(original?saving/original*100:0)+'%'};
 function products(){const q=dialog.querySelector('[data-bundle-search]').value.toLowerCase();dialog.querySelector('[data-bundle-products]').innerHTML=d.products.filter(p=>!q||c.localized(p.name).toLowerCase().includes(q)).map(p=>`<label class="aw-check"><input type="checkbox" data-product="${esc(p.id)}" ${selected.has(p.id)?'checked':''}><span>${esc(c.localized(p.name))}<small style="display:block">${money(StoreProducts.getEffectivePrice(p).price)}</small></span></label>`).join('')}
 let searchTimer,searchVersion=0;dialog.querySelector('[data-bundle-search]').oninput=()=>{if(!c.D.cloud){products();return}const version=++searchVersion;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{const rows=await c.D.lookupProducts(dialog.querySelector('[data-bundle-search]').value,[...selected]);if(version!==searchVersion||!dialog.isConnected)return;d.products=rows;products();sync()}catch(error){c.toast(error.message)}},250)};dialog.querySelector('[data-bundle-products]').onchange=e=>{if(!e.target.dataset.product)return;e.target.checked?selected.add(e.target.dataset.product):selected.delete(e.target.dataset.product);sync()};form.price.oninput=sync;products();sync();
 form.onsubmit=async e=>{e.preventDefault();const f=form.elements,original=total(),price=Number(f.price.value);if(selected.size<2||selected.size>8||price<=0||price>original||f.startsAt.value&&f.endsAt.value&&new Date(f.endsAt.value)<=new Date(f.startsAt.value)){form.querySelector('[role=alert]').textContent=t('راجع المنتجات والسعر ومواعيد العرض.','Check products, price and dates.');return}const next={...b,id:b.id||'bundle-'+Date.now(),title:{ar:f.titleAr.value.trim(),en:f.titleEn.value.trim()},description:{ar:f.description.value.trim(),en:f.description.value.trim()},productIds:[...selected],primaryId:[...selected][0],price,discount:original-price,startsAt:f.startsAt.value?new Date(f.startsAt.value).toISOString():'',endsAt:f.endsAt.value?new Date(f.endsAt.value).toISOString():'',enabled:f.enabled.checked};const result=await c.run(()=>c.D.write('bundles',[...c.data().bundles.filter(row=>row.id!==next.id),next]));if(result!==false){c.closeDialog();c.redraw()}};
}
